head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};

scwin.onpageload = function() {
	var rowJSON = {
		"Personal Info" : {
			"Name" : "Lee",
			"Age" : 50,
			"Married" : false
		},
		"Region" : "Seoul",
		"Carrier" : true
	};
	// Test, Test2 ~ Test11 / windowId 001 ~ 0011 창 11개 생성
	for (var i = 1; i <= 11; i++) {
		window1.createWindow({
			"title" : i == 1 ? "Test" : "Test" + i,
			"windowId" : "00" + i,
			"frameMode" : "wframe",
			"src" : "windowcontainer/sub1.xml",
			"options" : {
				"fixed" : true
			},
			"dataObject" : {
				"type" : "json",
				"name" : "windowParam",
				"data" : rowJSON
			}
		});
	}
};

scwin.checkVal = function() {
	return scwin.__getJq('#window1_nameLayer_' + $p.id + 'window1_subWindow9').hasClass('w2windowContainer_selectedNameLayer');
};
